-- Description: Current active record for SAT_ERC_POSITION_TYPE using ROW_NUMBER()
-- Generated by: bv pipeline generate transform with custom template
-- Satellite Type: SAT_ON_HUB
-- Parent: hub HUB_POSITION_TYPE

WITH RANKED_RECORDS AS (
SELECT
    POSITION_TYPE_HKEY,  -- hash key
    LOAD_DATE AS _CURRENT_ACTIVE_TIMESTAMP, -- used: LOAD_DATE
    -- Satellite Attributes
    POS_TYPE_ID     ,  -- is_business_key
    LOAD_DATE       ,  -- is_load_timestamp
    LOAD_CYCLE_ID   ,  -- is_load_cycle_id
    DELETE_FLAG     ,  -- is_delete_flag
    JOB_SEARCH      ,  -- is_other_attr
    MATCH_TYPE      ,  -- is_other_attr
    NAME            ,  -- is_other_attr
    _FIVETRAN_ACTIVE,  -- is_other_attr
    _FIVETRAN_END   ,  -- is_other_attr
    _FIVETRAN_START ,  -- is_other_attr
    _FIVETRAN_TRANS    -- is_other_attr
    ,
    ROW_NUMBER() OVER (
        PARTITION BY POSITION_TYPE_HKEY
        ORDER BY LOAD_DATE DESC
    ) AS row_num
FROM {{ source('eli_dv_rv', 'sat_erc_position_type') }}
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RECORDS
WHERE row_num = 1
AND DELETE_FLAG = 'N'
